            if (x.First < y.First || (x.First == y.First && x.Second > y.Second))
                return -1;
            return 1;
        }
    }

    public static long GetGcd(long a, long b) {
        while (true) {
            if (b == 0)
                return a;
            long a1 = a;
            a = b;
            b = a1 % b;
        }
    }

    public static void WriteYesNo(boolean x, String yes, String no) {
        if (x)
            System.out.println(yes);
        else
            System.out.println(no);
    }

    public static void WriteYesNo(boolean x) {
        WriteYesNo(x, "YES", "NO");
    }

