        String s = br.readLine();
        return Long.parseLong(s);
    }

    public static class Vertex {
        public int Was;
        public List<Integer> Edges = new ArrayList<>();
    }

    public static List<Vertex> Graph = new ArrayList<>();

    public static boolean Dfs(int u) {
        if (Graph.get(u).Was == 1) return true;
        if (Graph.get(u).Was == 2) return false;
        Graph.get(u).Was = 1;
        for (int t : Graph.get(u).Edges) {
            if (Dfs(t)) return true;
        }
        Graph.get(u).Was = 2;
        return false;
    }

